package vn.edu.eaut.lab8.bean; import jakarta.enterprise.context.SessionScoped; import jakarta.faces.application.FacesMessage; import jakarta.faces.context.FacesContext; import jakarta.inject.Named; import vn.edu.eaut.lab8.model.SinhVien; import vn.edu.eaut.lab8.repository.SinhVienRepository; import java.io.Serializable; import java.util.*; @Named("sinhVienBean") @SessionScoped public class SinhVienBean implements Serializable { private SinhVien sinhVien=new SinhVien(); private final SinhVienRepository repo=new SinhVienRepository(); private String keyword; public String save(){repo.add(sinhVien);msg("Thành công","Đã lưu sinh viên");sinhVien=new SinhVien();return null;} public void prepareEdit(int id){SinhVien x=repo.findById(id);if(x!=null)sinhVien=new SinhVien(x.getId(),x.getMaSinhVien(),x.getHoTen(),x.getEmail(),x.getLop());} public void update(){repo.update(sinhVien);msg("Thành công","Đã cập nhật sinh viên");sinhVien=new SinhVien();} public void delete(int id){repo.delete(id);msg("Thành công","Đã xóa sinh viên");} public List<SinhVien> getDsSinhVien(){return repo.search(keyword);} private void msg(String a,String b){FacesContext.getCurrentInstance().addMessage(null,new FacesMessage(FacesMessage.SEVERITY_INFO,a,b));} public SinhVien getSinhVien(){return sinhVien;} public void setSinhVien(SinhVien x){sinhVien=x;} public String getKeyword(){return keyword;} public void setKeyword(String x){keyword=x;} }
